static int ui_icon_asset_size_index(int size_px)
{
    if(size_px <= 0 || size_px > 58) {
        return 2;
    }
    if(size_px > 54) {
        return 1;
    }
    return 0;
}

const lv_image_dsc_t *ui_icon_asset_for_name_size(const char *name, int size_px)
{
    int size_index;

    if(name == NULL) {
        return NULL;
    }

    size_index = ui_icon_asset_size_index(size_px);
    for(size_t i = 0; i < sizeof(ui_icon_assets) / sizeof(ui_icon_assets[0]); ++i) {
        if(strcmp(name, ui_icon_assets[i].name) == 0) {
            return ui_icon_assets[i].image[size_index];
        }
    }

    return NULL;
}

const lv_image_dsc_t *ui_icon_asset_for_name(const char *name)
{
    return ui_icon_asset_for_name_size(name, 68);
}
